#include <stdio.h>
#include <math.h>

double f(double x) { return 2*x*x*x - 4*x*x + 3*x + 6; }

int main(void) {
    double x = 1.5, next;
    do {
        next = x - f(x) / (6*x*x - 8*x + 3);
        if (fabs(next - x) < 1e-8) break;
        x = next;
    } while (1);
    printf("%.6f\n", next);
    return 0;
}
